  m.IsDebuggingChanged+=(_,_)=>{if(!m.IsDebugging&&started){if(!done)Fail(new InvalidOperationException("Debuggee exited before the selected breakpoint"));Quit(done?0:70);}};
  deadline=new System.Threading.Timer(_=>m.Dispatcher.BeginInvoke(()=>Fail(new TimeoutException("Private debugger deadline exceeded"))),null,TimeSpan.FromSeconds(45),Timeout.InfiniteTimeSpan);
  CorDebugStartDebuggingOptions options=plan.Runtime=="framework"?new DotNetFrameworkStartDebuggingOptions():plan.Runtime=="core"?new DotNetStartDebuggingOptions{UseHost=false}:throw new InvalidOperationException("Select framework or core runtime");options.Filename=plan.Input;options.CommandLine=string.Join(" ",plan.Arguments.Select(Quote));options.WorkingDirectory=Path.GetDirectoryName(plan.Input);options.BreakKind=PredefinedBreakKinds.DontBreak;started=true;var error=m.Start(options);if(error!=null)throw new InvalidOperationException(error);
