 void Edit(){var p=plan!;if(p.ExpectedConstant is null||p.ReplacementConstant is null||!Path.IsPathFullyQualified(p.Output)||File.Exists(p.Output)||Path.GetFullPath(p.Output)==Path.GetFullPath(p.Input))throw new InvalidOperationException("A new output and explicit expected/replacement constants are required");
