   Save(new{state="completed",mode=p.Mode,pid=thread.Process.Id,thread=thread.Id,token=p.Token,offset=frame.FunctionOffset,parameters=values,frames=frames.Select(f=>new{token=f.FunctionToken,offset=f.FunctionOffset,module=f.Module?.Filename}).ToArray()});manager.Value.TerminateAll();
  }finally{foreach(var frame in frames)frame.Close();}}
